def _parse_args(summary: str) -> dict[str, Any]:
    """action_summary es `<tool_name>: <JSON>`. Devuelve dict o {} si falla."""
    if ":" not in summary:
        return {}
    _, _, payload = summary.partition(":")
    payload = payload.strip()
    if not payload.startswith("{"):
        return {}
    try:
        return json.loads(payload)
    except Exception:
        return {}


def _headline(tool: str, args: dict[str, Any]) -> str:
    """Título legible por humano a partir de tool + args."""
    if tool == "mcp_gke_patch_k8s_resource":
        kind = args.get("kind", "resource")
        name = args.get("name", "?")
        ns = args.get("namespace", "?")
        # Detectar si es rollout restart (annotation restartedAt).
        patch = args.get("patch") or {}
        annotations = (
            patch.get("spec", {})
                 .get("template", {})
                 .get("metadata", {})
                 .get("annotations", {})
            or {}
        )
        verb = "Restart" if "kubectl.kubernetes.io/restartedAt" in annotations else "Patch"
        return f"{verb} {kind}: {name} (ns={ns})"
    if tool == "mcp_gke_apply_k8s_manifest":
        kind = args.get("kind", "resource")
        name = args.get("name", "?")
        return f"Apply {kind}: {name}"
    if tool == "mcp_gke_delete_k8s_resource":
        kind = args.get("kind", "resource")
        name = args.get("name", "?")
        return f"Delete {kind}: {name}"
    if tool == "shell_exec":
        cmd = args.get("command") or args.get("cmd") or ""
        if cmd:
            return f"Shell: {cmd[:80]}"
    # Fallback: mostrar el tool raw.
    return tool


def build_blocks(approval: dict[str, Any], allowlist: frozenset[str]) -> list[dict[str, Any]]:
    tool = approval.get("tool_name", "?")
    summary = approval.get("action_summary") or approval.get("description") or "(sin detalle)"
    risk = approval.get("risk_level", "unknown")
    timeout = approval.get("timeout_secs", "?")
    agent = approval.get("agent_name", approval.get("agent_id", "?"))
    req_id = approval["id"]
    created = approval.get("created_at") or approval.get("requested_at") or ""

    args = _parse_args(summary)
    headline = _headline(tool, args)

    # Truncar summary si es muy largo (Slack limita ~3000 chars por block).
    if len(summary) > 2500:
        summary = summary[:2500] + "…"

    return [
