_NAME_RE = re.compile(r'"name"\s*:\s*"([^"]+)"')
_NS_RE = re.compile(r'"namespace"\s*:\s*"([^"]+)"')
_KIND_RE = re.compile(r'"kind"\s*:\s*"([^"]+)"')
_RESTART_RE = re.compile(r'restartedAt')


def _regex_extract(summary: str) -> dict[str, str]:
    """Fallback extractor: agarra name/namespace/kind desde cualquier string
    (incluye JSON truncado, summaries malformados, etc.)."""
    out: dict[str, str] = {}
    if m := _NAME_RE.search(summary):
        out["name"] = m.group(1)
    if m := _NS_RE.search(summary):
        out["namespace"] = m.group(1)
    if m := _KIND_RE.search(summary):
        out["kind"] = m.group(1)
    return out


def _parse_args(summary: str) -> dict[str, Any]:
    """action_summary es `<tool_name>: <JSON>`. Intenta parsear JSON completo;
    si falla (truncado, malformado), cae a regex para extraer al menos
    name/namespace/kind."""
    if ":" in summary:
        _, _, payload = summary.partition(":")
        payload = payload.strip()
        if payload.startswith("{"):
            try:
                return json.loads(payload)
            except Exception:
                pass
    # JSON parse falló → regex fallback (parcial pero útil)
    return _regex_extract(summary)


def _headline(tool: str, args: dict[str, Any], summary: str = "") -> str:
    """Título legible por humano a partir de tool + args. `summary` se usa
    como fallback para detectar patrones (e.g. restartedAt) cuando args
    es parcial."""
    if tool == "mcp_gke_patch_k8s_resource":
        kind = args.get("kind", "Deployment")
        name = args.get("name", "?")
        ns = args.get("namespace", "?")
        # Detectar si es rollout restart (annotation restartedAt).
        patch = args.get("patch") or {}
        annotations: dict[str, Any] = {}
        if isinstance(patch, dict):
            annotations = (
                patch.get("spec", {})
                     .get("template", {})
                     .get("metadata", {})
                     .get("annotations", {})
                or {}
            )
        # Fallback: buscá "restartedAt" en el summary crudo (útil cuando
        # patch viene como string JSON escapado).
        is_restart = (
            "kubectl.kubernetes.io/restartedAt" in annotations
            or bool(_RESTART_RE.search(summary))
        )
        verb = "Restart" if is_restart else "Patch"
        return f"{verb} {kind}: {name} (ns={ns})"

