async def forward_to_agent(
    cfg: Config,
    http: aiohttp.ClientSession,
    prompt: str,
    slack_ctx: dict,
) -> None:
    """POST to OpenFang agent API with Slack context for response routing."""
    body = {
        "message": prompt,
        "metadata": {
            "source": "kuma-trigger",
            "channel_id": slack_ctx["channel"],
            "thread_ts": slack_ctx["ts"],
            "event_id": slack_ctx.get("event_id", ""),
        },
    }
    url = f"{cfg.openfang_base}/api/agents/{cfg.agent_id}/messages"
    try:
        async with http.post(
            url, json=body, timeout=aiohttp.ClientTimeout(total=30)
        ) as r:
            txt = await r.text()
            if r.status >= 400:
                log.error("forward failed HTTP %s: %s", r.status, txt[:300])
            else:
                log.info("forwarded alert to agent=%s ts=%s", cfg.agent_id, slack_ctx["ts"])
    except Exception as e:
        log.error("forward crashed: %s", e)


async def poll_loop(
    cfg: Config, http: aiohttp.ClientSession, stop: asyncio.Event
) -> None:
    last_ts = load_last_ts(cfg.state_file)
    # If we have no state, start from "now" (don't reprocess history)
    if last_ts == "0":
        import time
        last_ts = f"{time.time():.6f}"
        save_last_ts(cfg.state_file, last_ts)

