# TI-1445 Fase 1 — alert rules MVP para proactive bot.
# 3 reglas críticas. Todas las queries van contra gmp-prod (datasource UID
# literal del frontend proxy de Google Managed Prometheus en prod-apps-454414).
# Ver .planning/phases/07-.../TI-1445-PLAN-FASE1.md para la justificación.

locals {
  gmp_prod_uid = "gmp-prod"
}

resource "grafana_rule_group" "infra_critical" {
  name             = "infra-critical"
  folder_uid       = grafana_folder.infra.uid
  interval_seconds = 60

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 1 — Pod CrashLoopBackOff (P0)
  # ─────────────────────────────────────────────────────────────────────────
  rule {
    name      = "Pod CrashLoopBackOff"
    for       = "5m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = local.gmp_prod_uid
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        expr          = "sum by (namespace, pod) (kube_pod_container_status_waiting_reason{reason=\"CrashLoopBackOff\"})"
        intervalMs    = 30000
        maxDataPoints = 43200
        refId         = "A"
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [0], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P0"
      team     = "infra"
    }

    annotations = {
      summary     = "Pod {{ $labels.pod }} en namespace {{ $labels.namespace }} está en CrashLoopBackOff"
      description = "El pod no arrancó correctamente durante >5min. Revisar logs + events + último rollout."
      runbook_url = "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"
    }

    is_paused = false
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 2 — Alta tasa de 5xx por deployment (Linkerd) (P1)
  # ─────────────────────────────────────────────────────────────────────────
  rule {
    name      = "High 5xx rate per deployment"
    for       = "5m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = local.gmp_prod_uid
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        expr          = "sum by (deployment, namespace) (rate(response_total{direction=\"inbound\",status_code=~\"5..\"}[5m])) / sum by (deployment, namespace) (rate(response_total{direction=\"inbound\"}[5m]))"
        intervalMs    = 30000
        maxDataPoints = 43200
        refId         = "A"
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [0.03], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P1"
      team     = "infra"
    }

    annotations = {
      summary     = "5xx rate > 3% en deployment {{ $labels.deployment }} (namespace {{ $labels.namespace }})"
      description = "La proporción de respuestas 5xx sobre el total de requests inbound supera 3% sostenido por 5min. Métrica origen: linkerd-proxy."
    }

    is_paused = false
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 3 — Disco de GCE VM >80% usado (P1)
  # ─────────────────────────────────────────────────────────────────────────
  # Fuente: Google Ops Agent (instalado en las 22 Rocky Linux VMs + 2 Windows).
  # Emite agent.googleapis.com/disk/percent_used que GMP expone como
  # agent_googleapis_com:disk_percent_used (naming Prometheus-friendly).
  rule {
    name      = "Disk usage > 80%"
    for       = "15m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = local.gmp_prod_uid
      relative_time_range {
        from = 900
        to   = 0
      }
      model = jsonencode({
        expr          = "max by (instance_name, device, project_id) (agent_googleapis_com:disk_percent_used{state=\"used\"})"
        intervalMs    = 60000
        maxDataPoints = 43200
        refId         = "A"
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [80], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P1"
      team     = "infra"
    }

    annotations = {
      summary     = "Disco {{ $labels.device }} >80% en VM {{ $labels.instance_name }}"
      description = "El filesystem del dispositivo {{ $labels.device }} está por encima del 80% sostenido por 15min. Project: {{ $labels.project_id }}. Escalar antes de que llegue a 90%."
    }

    is_paused = false
  }
}

