  # `instant_query` (validado 2026-04-23 post-apply). Hipótesis: el Google
  # Ops Agent envía los metrics directo a Cloud Monitoring (stackdriver),
  # no a GMP — por eso el endpoint lo expone pero nadie lo scrape.
  #
  # Follow-up: rewrite la rule usando el datasource `cloud-monitoring-main`
  # (stackdriver) con MQL nativo, o integrar Ops Agent → GMP via scrape job.
  # Tracking: TI-1445 Fase 1 follow-ups.
  rule {
    name      = "Disk usage > 80%"
    for       = "15m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = local.gmp_prod_uid
      relative_time_range {
        from = 900
        to   = 0
      }
      model = jsonencode({
        expr          = "max by (instance_name, device, project_id) (agent_googleapis_com:disk_percent_used{state=\"used\"})"
        intervalMs    = 60000
        maxDataPoints = 43200
        refId         = "A"
      })
